```Measure search head clustering writes to particular config objects via the conf.log file``` index=_internal source=*conf.log data.task=addCommit sourcetype=splunkd_conf `searchheadhosts`
| spath output=username path=data.asset_uri{0}
| spath output=app path=data.asset_uri{1}
| spath output=type path=data.asset_uri{2}
| spath output=objname path=data.asset_uri{3}
| fields objname, type, username, app, data.asset_id, host
| stats count by data.asset_id, objname, type, username, app, host
| fields - data.asset_id
| sort 0 - count
| table count, objname, type, app, username, host

index=_configtracker data.path=*/ui-prefs.conf sourcetype=splunk_configuration_change 
| spath path=data.changes{} 
| fields - data.changes{}.* 
| mvexpand data.changes{} 
| spath input=data.changes{} 
| spath input=data.changes{} path=properties{} 
| mvexpand properties{} 
| fields - properties{}.* 
| spath input=properties{} 
| table data.action data.path name *_value stanza
